import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


class DecisionTree:
    def __init__(self, max_depth=10, min_samples_split=20, min_samples_leaf=10):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.tree = None

    def _gini(self, y):
        if len(y) == 0:
            return 0
        p = y.mean()
        return 2 * p * (1 - p)

    def _best_split(self, X, y):
        n, d = X.shape
        best_gain = -1
        best_feat = None
        best_thresh = None
        parent_gini = self._gini(y)

        for feat in range(d):
            vals = X[:, feat]
            # Try a sample of thresholds
            percentiles = np.percentile(vals, np.arange(10, 100, 10))
            for thresh in percentiles:
                left_mask = vals <= thresh
                right_mask = ~left_mask
                nl, nr = left_mask.sum(), right_mask.sum()
                if nl < self.min_samples_leaf or nr < self.min_samples_leaf:
                    continue
                gain = parent_gini - (nl * self._gini(y[left_mask]) + nr * self._gini(y[right_mask])) / n
                if gain > best_gain:
                    best_gain = gain
                    best_feat = feat
                    best_thresh = thresh

        return best_feat, best_thresh, best_gain

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < self.min_samples_split:
            return {'leaf': True, 'pred': int(y.mean() >= 0.5)}

        feat, thresh, gain = self._best_split(X, y)
        if feat is None or gain <= 0:
            return {'leaf': True, 'pred': int(y.mean() >= 0.5)}

        left_mask = X[:, feat] <= thresh
        return {
            'leaf': False,
            'feat': feat,
            'thresh': thresh,
            'left': self._build(X[left_mask], y[left_mask], depth + 1),
            'right': self._build(X[~left_mask], y[~left_mask], depth + 1),
        }

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['pred']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])


class RandomForest:
    def __init__(self, n_trees=50, max_depth=8, min_samples_leaf=20, max_features=None):
        self.n_trees = n_trees
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.max_features = max_features
        self.trees = []
        self.feature_indices = []

    def fit(self, X, y):
        n, d = X.shape
        if self.max_features is None:
            self.max_features = int(np.sqrt(d))

        rng = np.random.RandomState(42)
        for _ in range(self.n_trees):
            # Bootstrap sample
            idx = rng.randint(0, n, size=n)
            # Random feature subset
            feat_idx = rng.choice(d, self.max_features, replace=False)
            tree = DecisionTree(max_depth=self.max_depth, min_samples_leaf=self.min_samples_leaf)
            tree.fit(X[np.ix_(idx, feat_idx)], y[idx])
            self.trees.append(tree)
            self.feature_indices.append(feat_idx)

    def predict(self, X):
        preds = np.zeros(len(X))
        for tree, feat_idx in zip(self.trees, self.feature_indices):
            preds += tree.predict(X[:, feat_idx])
        return (preds / self.n_trees >= 0.5).astype(int)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Random forest classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(np.float64)
    y_train = train[TARGET_COLUMN].values.astype(np.float64)
    X_test = test[feature_cols].values.astype(np.float64)

    rf = RandomForest(n_trees=100, max_depth=6, min_samples_leaf=50, max_features=10)
    rf.fit(X_train, y_train)
    preds = rf.predict(X_test)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)
